<script lang="ts">
	import { goto } from '$app/navigation'; import { register, login } from '$lib/api/auth'; import { auth } from '$lib/stores/auth.svelte'; import Button from '$lib/components/ui/Button.svelte'; import Card from '$lib/components/ui/Card.svelte'; import Input from '$lib/components/ui/Input.svelte'; import Alert from '$lib/components/ui/Alert.svelte'; let name = $state(''); let email = $state(''); let password = $state(''); let error = $state(''); let saving = $state(false);
	async function submit() { error = ''; saving = true; try { await register(email, password, name); const session = await login(email, password); auth.setSession(session.accessToken, session.refreshToken, session.user); goto('/'); } catch (reason) { error = reason instanceof Error ? reason.message : 'Unable to register.'; } finally { saving = false; } }
</script>
<div class="mx-auto max-w-md"><Card><form class="space-y-4" onsubmit={(event) => { event.preventDefault(); submit(); }}><div><h1 class="text-xl font-semibold">Create an account</h1><p class="text-sm text-slate-600">Passwords must contain at least 8 characters.</p></div>{#if error}<Alert>{error}</Alert>{/if}<label class="block text-sm font-medium">Name <Input bind:value={name} required /></label><label class="block text-sm font-medium">Email <Input bind:value={email} type="email" required /></label><label class="block text-sm font-medium">Password <Input bind:value={password} type="password" minlength={8} required /></label><Button type="submit" disabled={saving}>{saving ? 'Creating…' : 'Register'}</Button></form></Card></div>
